// Native pause-entry graphics candidate. Input is generated by the native
// ordinary-clock prefix, not an original LCD/poll recording. Copy payloads
// come from local extraction/native HUD publication, never comparison targets.
#include "air_pause_clock.h"
#include "air_pause_lcd.h"
#include <fstream>
#include <cstdio>

using namespace ticd;
int main(int argc,char** argv){
    if(argc!=3&&argc!=4){fprintf(stderr,"Usage: air-pause-probe native-graphics.txt bus.csv [paused-buttons.txt]\n");return 2;}
    try{
        std::ifstream input(argv[1]);std::ofstream bus(argv[2]),phases(std::string(argv[2])+".phases.csv"),graphics(std::string(argv[2])+".graphics.csv");
        AirClock clock;AirPauseLcd lcd;int tick,held,previous,pending;
        if(!bus||!phases||!graphics||!(input>>clock.now>>lcd.scrollX>>lcd.windowX>>lcd.windowY>>tick>>held>>previous>>pending))throw std::runtime_error("Invalid native graphics prefix");
        for(auto& object:lcd.objects)if(!(input>>object.x>>object.y))throw std::runtime_error("Missing native graphics objects");
        std::array<unsigned char,20> row{},saved{};std::array<unsigned char,128> font{},pauseFont{},restoreFont{};
        for(auto& byte:row){int value;if(!(input>>value)||value<0||value>255)throw std::runtime_error("Missing native HUD row");byte=static_cast<unsigned char>(value);}
        std::ifstream assets("build/pause.dat",std::ios::binary);std::array<char,8> magic{};
        assets.read(magic.data(),magic.size());
        if(std::string(magic.data(),magic.size())!="TICDPA01")throw std::runtime_error("Missing/invalid local pause assets");
        auto assetBytes=[&](auto& target){if(!assets.read(reinterpret_cast<char*>(target.data()),target.size()))throw std::runtime_error("Truncated local pause assets");};
        std::array<unsigned char,20> text{};assetBytes(pauseFont);assetBytes(restoreFont);assetBytes(text);
        char trailing;if(assets.get(trailing))throw std::runtime_error("Trailing local pause assets");font=restoreFont;
        graphics<<"phase,cycle";for(int i=0;i<20;++i)graphics<<",status"<<i;for(int i=0;i<128;++i)graphics<<",font"<<i;graphics<<'\n';
        auto snapshot=[&](const char* phase){graphics<<phase<<','<<clock.now;for(int value:row)graphics<<','<<value;for(int value:font)graphics<<','<<value;graphics<<'\n';};
        int extra;if(input>>extra)throw std::runtime_error("Unexpected native graphics data");
        if(!input.eof()||lcd.scrollX<0||lcd.scrollX>255)throw std::runtime_error("Invalid native graphics data");
        clock.nextStat=(clock.now/AirClock::Frame)*AirClock::Frame+AirClock::StatLine;
        clock.nextVBlank=(clock.now/AirClock::Frame)*AirClock::Frame+AirClock::VBlankLine;
        if(clock.nextStat<=clock.now)clock.nextStat+=AirClock::Frame;
        if(clock.nextVBlank<=clock.now)clock.nextVBlank+=AirClock::Frame;
        std::ifstream buttons;std::ofstream services;
        DisplayInput sampled;sampled.held=held;sampled.previous=previous;sampled.pressed=held&~previous;
        if(argc==4){buttons.open(argv[3]);services.open(std::string(argv[2])+".services.csv");
            if(!buttons||!services||pending!=-1)throw std::runtime_error("Missing paused buttons or unowned pending effect");
            services<<"service,cycle,tick,held,pressed,display,effects,music\n";
        }
        auto display=[&](bool ready)->int{
            if(!buttons.is_open())throw std::runtime_error("Pause-entry graphics crossed an unowned display service");
            int raw;if(!(buttons>>raw)||raw<0||raw>255||(raw&15)==15||ready)
                throw std::runtime_error("Missing/unsupported paused display input or resource gate");
            sampled.sample(raw);services<<clock.displays<<','<<clock.now<<','<<tick<<','<<sampled.held<<','<<sampled.pressed<<",160,64,60\n";
            tick=(tick+1)&65535;
            // Selector 1 (160), no new effect request (64), disabled music
            // driver (60), and shared DMA/input/bank/restore/bookkeeping (1592).
            return 1592+160+64+60;
        };
        bus<<"phase,kind,address,value,cycle\n";phases<<"phase,start,end,work,polls,failedPolls,bytes\n";
        const char* name="entry";
        auto status=[&](int64_t time){int mode=lcd.mode(time);bus<<name<<",read,65345,"<<mode<<','<<time<<'\n';return mode;};
        auto write=[&](unsigned address,unsigned char value,int64_t time){
            if(address>=0xc0a0&&address<0xc0b4){saved[address-0xc0a0]=value;return;}
            if(!lcd.writable(time))throw std::runtime_error("Native pause write is blocked");
            if(address>=0x9c00&&address<0x9c14)row[address-0x9c00]=value;
            else if(address>=0x8f80&&address<0x9000)font[address-0x8f80]=value;
            else throw std::runtime_error("Unowned native pause graphics destination");
            bus<<name<<",write,"<<address<<','<<int(value)<<','<<time<<'\n';
        };
        auto copy=[&](const char* phase,int size,unsigned destination,bool saveRow){
            name=phase;auto start=clock.now;
            auto result=airPauseCopy(clock,size,destination,display,status,[&](int i,int64_t time){
                if(saveRow){if(!lcd.readable(time))throw std::runtime_error("Native saved-row read is blocked");
                    bus<<name<<",read,"<<(0x9c00+i)<<','<<int(row[i])<<','<<time<<'\n';return row[i];}
                if(destination==0x9c00)return saved[i];
                return phase==std::string("copy1")?pauseFont[i]:restoreFont[i];
            },write);
            phases<<name<<','<<start<<','<<clock.now<<','<<result.cycles<<','<<result.polls<<','<<result.failedPolls<<','<<result.bytes<<'\n';
        };
        auto critical=[&](int cost){
            if(clock.now+cost>=std::min(clock.nextStat,clock.nextVBlank))
                throw std::runtime_error("Unowned pending interrupt across pause critical section");
            clock.now+=cost;
        };
        snapshot("enter");critical(192); // Pause critical section, before enabled graphics work.
        clock.work(60,display,false);copy("copy0",20,0xc0a0,true);
        clock.work(68,display,false);copy("copy1",128,0x8f80,false);
        name="script";auto start=clock.now;
        auto result=airPauseText(clock,text,display,status,write);
        phases<<name<<','<<start<<','<<clock.now<<','<<result.cycles<<','<<result.polls<<','<<result.failedPolls<<','<<result.bytes<<'\n';
        snapshot("wait");
        if(buttons.is_open()){
            for(int waits=0;;++waits){
                if(waits>=1000000)throw std::runtime_error("Pause counter waits did not complete");
                name="wait";auto begin=clock.now;clock.wait(display,false);
                phases<<name<<','<<begin<<','<<clock.now<<','<<clock.lastWaitWork<<",0,0,0\n";
                begin=clock.now;bool resume=sampled.pressed&8;int work=resume?28:32;
                clock.work(work,display,false);phases<<"wake,"<<begin<<','<<clock.now<<','<<work<<",0,0,0\n";
                if(resume)break;
            }
            clock.work(60,display,false);copy("copy2",20,0x9c00,false);
            clock.work(68,display,false);copy("copy3",128,0x8f80,false);
            snapshot("restoreAudio");
            auto begin=clock.now;critical(140);
            phases<<"restoreAudio,"<<begin<<','<<clock.now<<",140,0,0,0\n";
            begin=clock.now;clock.atomicWork(16,[]{},display,false);
            phases<<"return,"<<begin<<','<<clock.now<<",16,0,0,0\n";
            if(buttons>>extra)throw std::runtime_error("Unconsumed paused display samples");
        }
        fprintf(stderr,"Native pause graphics candidate completed; full pixels/PCM, audio software state, LCD startup and production integration remain outside this probe.\n");return 0;
    }catch(const std::exception& error){fprintf(stderr,"Pause probe: %s\n",error.what());return 1;}
}
